@Composable
fun GlyphIcon(glyph: Glyph, tint: Color, size: Dp, modifier: Modifier = Modifier) {
    val path = remember(glyph) { PathParser().parsePathString(glyph.pathData).toPath() }
    Canvas(modifier.size(size)) {
        val k = this.size.minDimension / 256f
        scale(k, k, pivot = Offset.Zero) { drawPath(path, tint) }
    }
}
